import csv, json, subprocess

def expected(since=None):
    rows, rev, tax, rr, pp = [], 0.0, 0.0, {}, {}
    with open('sales.csv') as f:
        rd = csv.reader(f)
        next(rd)
        for row in rd:
            if len(row) < 5:
                continue
            if since and row[0] < since:
                continue
            try:
