            except ValueError:
                continue
            try:
                pr = float(row[4])
            except ValueError:
                continue
            amt = u * pr
            if u >= 50:
                amt -= amt * 0.1
            elif u >= 10:
                amt -= amt * 0.05
            tx = {'north': .07, 'south': .05, 'east': .06, 'west': .08}.get(row[1], 0) * amt
            rev += amt; tax += tx
            rr[row[1]] = rr.get(row[1], 0) + amt
            pp[row[2]] = pp.get(row[2], 0) + amt
            rows.append(row)
    top = max(pp, key=lambda k: pp[k]) if pp else None
    return {
        'rows': rows,
        'total_revenue': round(rev, 2),
        'total_tax': round(tax, 2),
        'by_region': {k: round(rr[k], 2) for k in sorted(rr)},
        'by_product': {k: round(pp[k], 2) for k in sorted(pp)},
        'top_product': top,
    }

for since in [None, '2024-01-21', '2024-01-22', '2024-03-01', '2024-06-01', '2025-01-01']:
    cmd = ['python3', 'report.py', 'sales.csv', '--format', 'json']
    if since:
        cmd += ['--since', since]
    got = json.loads(subprocess.check_output(cmd))
    exp = expected(since)
    assert got == exp, (since, got, exp)
    print(since, 'ok rows=', len(got['rows']), 'revenue=', got['total_revenue'], 'top=', got['top_product'])
